

CREATE TABLE IF NOT EXISTS `migrations` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `migration` VARCHAR(255) not null, `batch` INT not null);
CREATE TABLE IF NOT EXISTS `users` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `name` VARCHAR(255) not null, `email` VARCHAR(255), `role` VARCHAR(255) not null default 'customer', `permissions` TEXT, `phone` VARCHAR(255), `doc_number` VARCHAR(255), `passport_number` VARCHAR(255), `birth_DATE` DATE, `address` TEXT, `history_json` TEXT, `notes` TEXT, `email_verified_at` DATETIME, `password` VARCHAR(255) not null, `remember_token` VARCHAR(255), `created_at` DATETIME, `upDATEd_at` DATETIME);
CREATE TABLE IF NOT EXISTS `password_reset_tokens` (`email` VARCHAR(255) not null, `token` VARCHAR(255) not null, `created_at` DATETIME, primary key (`email`));
CREATE TABLE IF NOT EXISTS `sessions` (`id` VARCHAR(255) not null, `user_id` INT, `ip_address` VARCHAR(255), `user_agent` TEXT, `payload` TEXT not null, `last_activity` INT not null, primary key (`id`));
CREATE TABLE IF NOT EXISTS `cache` (`key` VARCHAR(255) not null, `value` TEXT not null, `expiration` INT not null, primary key (`key`));
CREATE TABLE IF NOT EXISTS `cache_locks` (`key` VARCHAR(255) not null, `owner` VARCHAR(255) not null, `expiration` INT not null, primary key (`key`));
CREATE TABLE IF NOT EXISTS `jobs` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `queue` VARCHAR(255) not null, `payload` TEXT not null, `attempts` INT not null, `reserved_at` INT, `available_at` INT not null, `created_at` INT not null);
CREATE TABLE IF NOT EXISTS `job_batches` (`id` VARCHAR(255) not null, `name` VARCHAR(255) not null, `total_jobs` INT not null, `pending_jobs` INT not null, `failed_jobs` INT not null, `failed_job_ids` TEXT not null, `options` TEXT, `cancelled_at` INT, `created_at` INT not null, `finished_at` INT, primary key (`id`));
CREATE TABLE IF NOT EXISTS `failed_jobs` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `uuid` VARCHAR(255) not null, `connection` TEXT not null, `queue` TEXT not null, `payload` TEXT not null, `exception` TEXT not null, `failed_at` DATETIME not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS `service_types` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `name` VARCHAR(255) not null, `key` VARCHAR(255) not null, `icon` VARCHAR(255), `is_active` TINYINT(1) not null default '1', `created_at` DATETIME, `upDATEd_at` DATETIME);
CREATE TABLE IF NOT EXISTS `leads` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `customer_id` INT, `travel_package_id` INT, `source` VARCHAR(255) not null, `status` VARCHAR(255) check (`status` in ('new', 'contacted', 'closed')) not null, `customer_name` VARCHAR(255) not null, `customer_phone` VARCHAR(255) not null, `customer_email` VARCHAR(255), `customer_budget` VARCHAR(255), `raw_message` TEXT not null, `ai_data` TEXT, `ai_summary` TEXT, `needs_human_attention` TINYINT(1) not null default '0', `created_at` DATETIME, `upDATEd_at` DATETIME, foreign key(`customer_id`) references `users`(`id`) on delete set null, foreign key(`travel_package_id`) references `travel_packages`(`id`) on delete set null);
CREATE TABLE IF NOT EXISTS `bookings` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `lead_id` INT, `customer_id` INT, `file_number` VARCHAR(255) not null, `holder_name` VARCHAR(255) not null, `destination` VARCHAR(255), `nights` INT default '0', `passengers` INT default '1', `travel_DATE` DATETIME, `total_cost` DECIMAL(19,4) not null default '0', `total_sell` DECIMAL(19,4) not null default '0', `profit` DECIMAL(19,4) not null default '0', `status` VARCHAR(255) check (`status` in ('borrador', 'presupuesto', 'senado', 'emitido', 'cancelado')) not null default 'borrador', `currency` VARCHAR(255) not null default 'USD', `exchange_rate` DECIMAL(19,4) not null default '1', `valid_until` DATETIME, `internal_notes` TEXT, `notes` TEXT, `created_at` DATETIME, `upDATEd_at` DATETIME, foreign key(`lead_id`) references `leads`(`id`) on delete set null, foreign key(`customer_id`) references `users`(`id`) on delete set null);
CREATE TABLE IF NOT EXISTS `booking_items` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `booking_id` INT not null, `supplier_id` INT, `service_type_id` INT, `description` VARCHAR(255) not null, `currency` VARCHAR(255) not null default 'USD', `exchange_rate` DECIMAL(19,4) not null default '1', `cost` DECIMAL(19,4) not null default '0', `sell` DECIMAL(19,4) not null default '0', `created_at` DATETIME, `upDATEd_at` DATETIME, foreign key(`booking_id`) references `bookings`(`id`) on delete cascade, foreign key(`supplier_id`) references `suppliers`(`id`) on delete restrict, foreign key(`service_type_id`) references `service_types`(`id`) on delete set null);
CREATE TABLE IF NOT EXISTS `transactions` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `booking_id` INT, `supplier_id` INT, `supplier_account_id` INT, `financial_account_id` INT, `transaction_category_id` INT, `payer_name` VARCHAR(255), `type` VARCHAR(255) check (`type` in ('cobro', 'pago')) not null, `amount` DECIMAL(19,4) not null, `currency` VARCHAR(255) not null, `exchange_rate` DECIMAL(19,4), `amount_usd_fixed` DECIMAL(19,4), `DATE` DATETIME, `method` VARCHAR(255) not null, `notes` TEXT, `reference` VARCHAR(255), `attachment_path` VARCHAR(255), `payable_type` VARCHAR(255), `payable_id` INT, `tax_details` TEXT, `created_at` DATETIME, `upDATEd_at` DATETIME, foreign key(`booking_id`) references `bookings`(`id`) on delete set null, foreign key(`supplier_id`) references `suppliers`(`id`) on delete set null, foreign key(`supplier_account_id`) references `supplier_accounts`(`id`) on delete set null, foreign key(`financial_account_id`) references `financial_accounts`(`id`) on delete set null, foreign key(`transaction_category_id`) references `transaction_categories`(`id`) on delete set null);
CREATE TABLE IF NOT EXISTS `personal_access_tokens` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `tokenable_type` VARCHAR(255) not null, `tokenable_id` INT not null, `name` TEXT not null, `token` VARCHAR(255) not null, `abilities` TEXT, `last_used_at` DATETIME, `expires_at` DATETIME, `created_at` DATETIME, `upDATEd_at` DATETIME);
CREATE TABLE IF NOT EXISTS `suppliers` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `name` VARCHAR(255) not null, `contact_name` VARCHAR(255), `contact_email` VARCHAR(255), `contact_phone` VARCHAR(255), `website` VARCHAR(255), `service_type_id` INT, `category` VARCHAR(255), `location` VARCHAR(255), `cuit` VARCHAR(255), `bank_name` VARCHAR(255), `cbu` VARCHAR(255), `alias` VARCHAR(255), `account_number` VARCHAR(255), `notes` TEXT, `created_at` DATETIME, `upDATEd_at` DATETIME, foreign key(`service_type_id`) references `service_types`(`id`) on delete set null);
CREATE TABLE IF NOT EXISTS `supplier_accounts` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `supplier_id` INT not null, `bank_name` VARCHAR(255) not null, `account_number` VARCHAR(255), `cbu` VARCHAR(255), `alias` VARCHAR(255), `currency` VARCHAR(255) not null default 'ARS', `notes` TEXT, `created_at` DATETIME, `upDATEd_at` DATETIME, foreign key(`supplier_id`) references `suppliers`(`id`) on delete cascade);
CREATE TABLE IF NOT EXISTS `financial_accounts` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `name` VARCHAR(255) not null, `currency` VARCHAR(255) not null default 'ARS', `balance` DECIMAL(19,4) not null default '0', `cbu` VARCHAR(255), `is_active` TINYINT(1) not null default '1', `created_at` DATETIME, `upDATEd_at` DATETIME);
CREATE TABLE IF NOT EXISTS `transaction_categories` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `name` VARCHAR(255) not null, `type` VARCHAR(255) not null, `is_system` TINYINT(1) not null default '0', `created_at` DATETIME, `upDATEd_at` DATETIME);
CREATE TABLE IF NOT EXISTS `messages` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `lead_id` INT not null, `role` VARCHAR(255) not null, `content` TEXT not null, `created_at` DATETIME, `upDATEd_at` DATETIME, foreign key(`lead_id`) references `leads`(`id`) on delete cascade);
CREATE TABLE IF NOT EXISTS `travel_packages` (`id` INT AUTO_INCREMENT PRIMARY KEY not null, `title` VARCHAR(255) not null, `slug` VARCHAR(255) not null, `destination` VARCHAR(255) not null, `nights` INT not null, `tags` TEXT, `price_from` DECIMAL(19,4) not null, `currency` VARCHAR(255) not null default 'USD', `cover_image` VARCHAR(255), `gallery` TEXT, `summary` TEXT, `description` TEXT, `itinerary` TEXT, `services` TEXT, `included` TEXT, `excluded` TEXT, `is_active` TINYINT(1) not null default '1', `created_at` DATETIME, `upDATEd_at` DATETIME);
CREATE TABLE IF NOT EXISTS `notifications` (`id` VARCHAR(255) not null, `type` VARCHAR(255) not null, `notifiable_type` VARCHAR(255) not null, `notifiable_id` INT not null, `data` TEXT not null, `read_at` DATETIME, `created_at` DATETIME, `upDATEd_at` DATETIME, primary key (`id`));
CREATE UNIQUE INDEX `users_email_unique` on `users` (`email`);
CREATE UNIQUE INDEX `users_phone_unique` on `users` (`phone`);
CREATE INDEX `sessions_user_id_index` on `sessions` (`user_id`);
CREATE INDEX `sessions_last_activity_index` on `sessions` (`last_activity`);
CREATE INDEX `jobs_queue_index` on `jobs` (`queue`);
CREATE UNIQUE INDEX `failed_jobs_uuid_unique` on `failed_jobs` (`uuid`);
CREATE UNIQUE INDEX `service_types_key_unique` on `service_types` (`key`);
CREATE INDEX `leads_customer_phone_index` on `leads` (`customer_phone`);
CREATE INDEX `leads_customer_email_index` on `leads` (`customer_email`);
CREATE UNIQUE INDEX `bookings_file_number_unique` on `bookings` (`file_number`);
CREATE INDEX `transactions_payable_type_payable_id_index` on `transactions` (`payable_type`, `payable_id`);
CREATE INDEX `personal_access_tokens_tokenable_type_tokenable_id_index` on `personal_access_tokens` (`tokenable_type`, `tokenable_id`);
CREATE UNIQUE INDEX `personal_access_tokens_token_unique` on `personal_access_tokens` (`token`);
CREATE INDEX `personal_access_tokens_expires_at_index` on `personal_access_tokens` (`expires_at`);
CREATE UNIQUE INDEX `travel_packages_slug_unique` on `travel_packages` (`slug`);
CREATE INDEX `notifications_notifiable_type_notifiable_id_index` on `notifications` (`notifiable_type`, `notifiable_id`);

